import sys,collections,heapq,itertools,functools,bisect
def solve(data):
    v=list(map(int,data.split()));n=v[0];a=[v[1+i*n:1+(i+1)*n] for i in range(n)];best=10**30
    def f(i,mask,s):
        nonlocal best
        if s>=best:return
        if i==n:best=s;return
        for j in range(n):
            if not(mask>>j&1):f(i+1,mask|1<<j,s+a[i][j])
    f(0,0,0);return best

if __name__=="__main__":
    a=solve(sys.stdin.buffer.read().decode())
    print(" ".join(map(str,a)) if isinstance(a,(list,tuple)) else a)
